        <li>폼 3개</li>
        <li>월 응답 100건</li>
      </ul>
    </article>

    <article class="plan plan--recommended" data-paid aria-labelledby="plan-pro">
      <div class="plan__head">
        <h3 id="plan-pro" class="plan__name">Pro</h3>
        <span class="plan__label">가장 인기</span>
      </div>
      <div class="plan__pricing">
        <p class="plan__price">
          <span class="sr-only">월</span>
          <span class="plan__amount" data-monthly="19,000원" data-annual="15,000원">15,000원</span>
          <span class="plan__suffix" aria-hidden="true">/월</span>
