<script>
(() => {
  const root = document.querySelector('[data-pricing]');
  if (!root) return;
  const announcer = root.querySelector('[data-announcer]');
  const swaps = root.querySelectorAll('[data-monthly][data-annual]');

  function render(cycle, announce = false) {
    root.dataset.cycle = cycle;
    swaps.forEach((el) => { el.textContent = el.dataset[cycle]; });
    if (announce) announcer.textContent = summary(cycle);
  }

  function summary(cycle) {
    const head = cycle === 'annual'
      ? '연간 결제 가격으로 바뀌었습니다.'
      : '월간 결제 가격으로 바뀌었습니다.';
    const items = [...root.querySelectorAll('.plan[data-paid]')].map((card) => {
      const name = card.querySelector('.plan__name').textContent.trim();
      const amount = card.querySelector('.plan__amount').textContent.trim();
      const billing = card.querySelector('.plan__billing').textContent.trim();
      return `${name} 월 ${amount}, ${billing}`;
    });
    return `${head} ${items.join('. ')}. VAT 별도.`;
  }

  root.querySelectorAll('input[name="billing"]').forEach((radio) => {
    radio.addEventListener('change', () => { if (radio.checked) render(radio.value, true); });
  });

  // 뒤로가기 등으로 브라우저가 복원한 라디오 상태와 동기화 (읽어 주지 않음)
  const checked = root.querySelector('input[name="billing"]:checked');
  render(checked ? checked.value : 'annual');

  // ── CTA 로딩 상태 ──
  root.addEventListener('click', async (e) => {
    const btn = e.target.closest('.plan__cta');
    if (!btn || btn.getAttribute('aria-disabled') === 'true') return; // 중복 제출 방지
    setLoading(btn, true);
    try {
      await startCheckout(btn.dataset.plan, root.dataset.cycle);
    } finally {
      setLoading(btn, false);
    }
  });

  function setLoading(btn, on) {
    const text = btn.querySelector('.plan__cta-text');
    if (!btn.dataset.label) btn.dataset.label = text.textContent;
    btn.setAttribute('aria-disabled', on ? 'true' : 'false');
    text.textContent = on ? '처리 중…' : btn.dataset.label;
    if (on) announcer.textContent = `${btn.dataset.label}, 처리 중입니다.`;
  }

  // 데모용. 실제로는 가입·체험 API를 호출한 뒤 라우팅
  function startCheckout(plan, cycle) {
    return new Promise((resolve) => setTimeout(resolve, 1500));
  }
})();
</script>
</body>
</html>
```

## 2. 스펙 표

범례: **⚠ 값 변경** · **✚ 노트에 없어 추가** · **(제안)** 신규 토큰 필요

| 요소 | 속성 | 값 (토큰) | 비고 |
|---|---|---|---|
| 토글 | height | 40px | 토큰 없음 |
| | radius | `--radius-full` | **⚠** 20px → pill. 높이 40px에서는 시각적으로 같음 |
| | 선택 bg | `--primary-600` | **⚠** #2F6FEB → #2F6FED (오타로 판단) |
| | 선택 text | `--white` (제안) | #FFFFFF |
| | 비선택 text | `--gray-600` | |
| | 컨테이너 | padding `--space-1`, border 1px `--gray-200` (제안) | **✚** |
| | 세그먼트 padding-x | `--space-4` | **✚** |
| | hover | 비선택: text `--primary-700` / 선택: bg `--primary-700` | **✚** |
| 할인 배지 | bg / text | `--success-50` / `--success-700` (제안) | #E8F7EE / #1F7A45 |
| | font / radius / padding-x | 12px · `--radius-full` · `--space-2` | radius·padding은 **✚** |
| 카드 | width / padding | 320px · `--space-6` | |
| | 카드 간 gap | `--space-4` | **⚠** 14px → 16px |
| | radius / border | `--radius-lg` · 1px `--gray-200` (제안) | |
| | 내부 gap | `--space-4` | **✚** |
| Pro 카드 | 테두리 | 1px border + 1px shadow `--primary-600` | **⚠** 구현 방식만 변경 (시각 2px, 내용 밀림 없음) |
| | "가장 인기" | bg `--primary-600`, text `--white`, 12px | **✚** 스타일 미지정 |
| 가격 | 금액 | 40/48px, 600, tabular-nums | tabular-nums는 **✚** |
| | "/월" | 16px `--gray-500` | |
| | "VAT 별도" | 12px `--gray-500` | **✚** |
| | 결제 줄 | 14/20px `--gray-500`, min-height 20px | **✚** |
| CTA | height / radius | 44px · `--radius-md` | |
| | bg / text | `--primary-600` · `--white` | |
| | hover / 로딩 | `--primary-700` / 스피너 + "처리 중…" | **✚** |
| 기능 목록 | text / icon | 14/20px · 16px, `--primary-600` | 아이콘 색은 **✚** |
| | row gap | `--space-3` | **⚠** 10px → 12px |
| | 아이콘–텍스트 | `--space-2` | **✚** |
| 공통 | focus ring | 2px `--primary-600`, offset 2px | **✚** |
| 반응형 | ≥1040px | 3열 | |
| | <1040px | 1열(최대 320px), Pro 먼저(CSS order) | |

## 3. 접근성 노트

**토글 시맨틱과 키보드**
- `fieldset` + `legend` "결제 주기" 안에 네이티브 라디오 2개를 둡니다. 스크린리더는 "연간, 20% 할인, 라디오 버튼, 선택됨, 2개 중 2번째"처럼 읽습니다.
- Tab: 그룹에 들어가면 선택된 항목에 포커스가 갑니다.
- ←→/↑↓: 항목을 이동하면서 즉시 선택합니다. 브라우저 기본 동작이므로 별도 구현은 필요 없습니다.
- `role="tab"`이나 커스텀 버튼으로 바꾸지 마십시오.

**가격이 바뀔 때 읽어 주는 내용**
- 가격 요소 자체에는 live 속성을 걸지 않습니다. 카드마다 따로 읽히는 것을 막기 위해서입니다.
- 대신 `aria-live="polite"` 영역 하나에서 요약을 한 번만 읽어 줍니다. 예: "연간 결제 가격으로 바뀌었습니다. Pro 월 15,000원, 연 190,000원 결제. Business 월 39,000원, 연 468,000원 결제. VAT 별도."
- 첫 로드 때는 읽지 않습니다.
- "/월"은 `aria-hidden`으로 숨기고 sr-only "월"을 앞에 두어 "월 15,000원"으로 읽히게 했습니다.
- CTA 로딩 중에는 `aria-disabled`를 써서 포커스를 유지하고, "처리 중입니다"를 읽어 줍니다.

